// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {StaxLPStaking} from "../src/StaxLPStaking.sol";

contract InvMutTest is Test {
    StaxLPStaking c;
    function setUp() public { c = new StaxLPStaking(address(this), address(this)); }
    function testFuzz_property(address actor) public {
        vm.assume(actor != address(this));
        Caller caller = new Caller();
        (bool success, bytes memory data) = address(caller).call(abi.encodeWithSignature("callOwner(address)", address(c)));
        require(success, "Caller failed");
        address returnedOwner = abi.decode(data, (address));
        assertTrue(returnedOwner == address(this));
    }
}

contract Caller {
    function callOwner(address target) public view returns (address) {
        return StaxLPStaking(target).owner();
    }
}
